package ama.minutes;
import org.junit.jupiter.api.Test;import org.springframework.jdbc.core.JdbcTemplate;import java.nio.file.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class Task09ControlledAdminIT {
 @Test void explicitCommandInstallsRealTemplateReleaseAndCapacityWithPrivateLaunchFiles()throws Exception {
  var source=Task09Source.open();var j=new JdbcTemplate(source);Path owner=Files.createTempDirectory(Path.of(System.getenv("AMA_TASK09_RUN_ROOT")),"admin-test-");Files.setPosixFilePermissions(owner,java.nio.file.attribute.PosixFilePermissions.fromString("rwx------"));String template=UUID.randomUUID().toString(),revision=UUID.randomUUID().toString();Path config=owner.resolve("install.properties");String text="mode=CONTROLLED_INSTALLATION\ntemplateId="+template+"\nrevisionId="+revision+"\nrelease=task09.admin."+UUID.randomUUID()+"\nprompt=Controlled synthetic minutes.\nport=42769\nmodelCapacity=1\nmodelConfigRevision=1\n";Files.createFile(config,java.nio.file.attribute.PosixFilePermissions.asFileAttribute(java.nio.file.attribute.PosixFilePermissions.fromString("rw-------")));Files.writeString(config,text);
  Class<?> type=assertDoesNotThrow(()->Class.forName("ama.minutes.ControlledMinutesAdmin"));var result=type.getMethod("install",javax.sql.DataSource.class,Path.class).invoke(null,source,config);String pin=(String)result.getClass().getMethod("indexSha").invoke(result);assertTrue(pin.matches("[0-9a-f]{64}"));assertEquals(revision,j.queryForObject("SELECT current_revision_id FROM minutes_template WHERE id=?",String.class,template));assertEquals(template,j.queryForObject("SELECT template_id FROM template_revision WHERE id=?",String.class,revision));assertEquals(1,j.queryForObject("SELECT capacity FROM model_capacity WHERE model='CONTROLLED_MINUTES_V1'",Integer.class));assertEquals(0,j.queryForObject("SELECT COUNT(*) FROM generation_input WHERE template_revision_id=?",Integer.class,revision));
  for(String name:List.of("minutes.properties","provider.properties","provider.secret","installation.json")){var path=owner.resolve(name);assertTrue(Files.isRegularFile(path));assertEquals(java.nio.file.attribute.PosixFilePermissions.fromString("rw-------"),Files.getPosixFilePermissions(path));}assertEquals(0,Files.list(owner.resolve("provider-store")).count());assertFalse(Files.exists(owner.resolve("provider.ready")));assertEquals(result,type.getMethod("install",javax.sql.DataSource.class,Path.class).invoke(null,source,config));
  var data=Files.readString(owner.resolve("installation.json"));assertFalse(data.contains(Files.readString(owner.resolve("provider.secret"))));Files.writeString(Path.of(System.getenv("AMA_TASK09_EVIDENCE_WINDOW")).resolve("actual-admin-installation.json"),data);
 }
}
